function countBalancedBlocks(s: string): number {
  let total = 0;
  for (let i = 0; i < s.length; i++) {
    let first = 0, second = 0;
    for (let j = i; j < s.length; j++) {
      if (s[j] === s[i]) {
        if (second > 0) break; // a third block would start
        first++;
      } else second++;
      if (first === second) { total++; break; }
    }
  }
  return total;
}

